export const getGetDeliveryTrackingUrl = (deliveryId: string) => {
  return `/api/tracking/${deliveryId}`;
};

export const getDeliveryTracking = async (
  deliveryId: string,
  options?: RequestInit,
): Promise<TrackingInfo> => {
  return customFetch<TrackingInfo>(getGetDeliveryTrackingUrl(deliveryId), {
    ...options,
    method: "GET",
  });
};

export const getGetDeliveryTrackingQueryKey = (deliveryId: string) => {
  return [`/api/tracking/${deliveryId}`] as const;
};

export const getGetDeliveryTrackingQueryOptions = <
  TData = Awaited<ReturnType<typeof getDeliveryTracking>>,
  TError = ErrorType<ErrorResponse>,
>(
  deliveryId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getDeliveryTracking>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetDeliveryTrackingQueryKey(deliveryId);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getDeliveryTracking>>
  > = ({ signal }) =>
    getDeliveryTracking(deliveryId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!deliveryId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getDeliveryTracking>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

